Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='fewerconcepts', at=datetime(2026, 11, 26, 0, 0, 0), actor='assistant', title='Of two designs, take the one with fewer concepts, and run cleanup passes after each series', body='A design note counts the concepts a reader must hold before and after the change. The smallest version is a warning sign if it adds a type or drops a capability. After each feature series, look for duplicated shapes and land a pass that deletes more than it adds. A review asks if the change is a new mechanism or a composition of existing ones.', rationale='Small general pieces that compose make the code smaller, and copies drift apart.', supersedes=()))